CREATE TYPE "HeritageParentType" AS ENUM ('MOTHER','FATHER');
CREATE TYPE "RegistryAffiliation" AS ENUM ('YES','NO','UNKNOWN');
CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
ALTER TABLE "DogIdentity" ADD COLUMN "nickname" TEXT;
ALTER TABLE "Competition" ADD COLUMN "heroStorageKey" TEXT, ADD COLUMN "heroFileName" TEXT, ADD COLUMN "heroContentType" TEXT, ADD COLUMN "heroSizeBytes" INTEGER;
CREATE UNIQUE INDEX "Competition_heroStorageKey_key" ON "Competition"("heroStorageKey");
CREATE TABLE "DogHeritageParent" ("id" TEXT PRIMARY KEY,"dogId" TEXT NOT NULL,"parentType" "HeritageParentType" NOT NULL,"isUnknown" BOOLEAN NOT NULL DEFAULT false,"parentName" TEXT,"barkBoothRegistryNumber" TEXT,"breed" TEXT,"colourMarkings" TEXT,"registryAffiliated" "RegistryAffiliation" NOT NULL DEFAULT 'UNKNOWN',"registryName" TEXT,"registryNumber" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DogHeritageParent_dogId_fkey" FOREIGN KEY("dogId") REFERENCES "DogIdentity"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "DogHeritageParent_dogId_parentType_key" ON "DogHeritageParent"("dogId","parentType"); CREATE INDEX "DogHeritageParent_barkBoothRegistryNumber_idx" ON "DogHeritageParent"("barkBoothRegistryNumber");
CREATE TABLE "DogVaccination" ("id" TEXT PRIMARY KEY,"dogId" TEXT NOT NULL,"name" VARCHAR(160) NOT NULL,"vaccinated" BOOLEAN NOT NULL DEFAULT false,"administeredAt" TIMESTAMP(3),"nextDueAt" TIMESTAMP(3),"veterinaryPractice" VARCHAR(200),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DogVaccination_dogId_fkey" FOREIGN KEY("dogId") REFERENCES "DogIdentity"("id") ON DELETE CASCADE); CREATE INDEX "DogVaccination_dogId_nextDueAt_idx" ON "DogVaccination"("dogId","nextDueAt");
CREATE TABLE "CompetitionJudge" ("id" TEXT PRIMARY KEY,"competitionId" TEXT NOT NULL,"name" VARCHAR(160) NOT NULL,"roleTitle" VARCHAR(160),"organisation" VARCHAR(200),"biography" TEXT,"profession" TEXT,"judgingFocus" TEXT,"guestJudge" BOOLEAN NOT NULL DEFAULT false,"displayOrder" INTEGER NOT NULL DEFAULT 0,"imageStorageKey" TEXT,"imageFileName" TEXT,"imageContentType" TEXT,"imageSizeBytes" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CompetitionJudge_competitionId_fkey" FOREIGN KEY("competitionId") REFERENCES "Competition"("id") ON DELETE CASCADE); CREATE UNIQUE INDEX "CompetitionJudge_imageStorageKey_key" ON "CompetitionJudge"("imageStorageKey"); CREATE INDEX "CompetitionJudge_competitionId_displayOrder_idx" ON "CompetitionJudge"("competitionId","displayOrder");
CREATE TABLE "NewsPost" ("id" TEXT PRIMARY KEY,"authorId" TEXT NOT NULL,"competitionId" TEXT,"slug" VARCHAR(160) NOT NULL,"title" VARCHAR(200) NOT NULL,"summary" TEXT,"body" TEXT NOT NULL,"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"featured" BOOLEAN NOT NULL DEFAULT false,"publishedAt" TIMESTAMP(3),"imageStorageKey" TEXT,"imageFileName" TEXT,"imageContentType" TEXT,"imageSizeBytes" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NewsPost_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "User"("id") ON DELETE RESTRICT,CONSTRAINT "NewsPost_competitionId_fkey" FOREIGN KEY("competitionId") REFERENCES "Competition"("id") ON DELETE SET NULL); CREATE UNIQUE INDEX "NewsPost_slug_key" ON "NewsPost"("slug"); CREATE UNIQUE INDEX "NewsPost_imageStorageKey_key" ON "NewsPost"("imageStorageKey"); CREATE INDEX "NewsPost_status_publishedAt_idx" ON "NewsPost"("status","publishedAt");
CREATE TABLE "Event" ("id" TEXT PRIMARY KEY,"authorId" TEXT NOT NULL,"name" VARCHAR(200) NOT NULL,"description" TEXT NOT NULL,"location" VARCHAR(240),"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"externalUrl" VARCHAR(2048),"organiser" VARCHAR(200),"status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"cancelled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Event_authorId_fkey" FOREIGN KEY("authorId") REFERENCES "User"("id") ON DELETE RESTRICT); CREATE INDEX "Event_status_startsAt_idx" ON "Event"("status","startsAt");
